raw:
{
  "spells": [
    {
      "id": "spell_earth_01",
      "theory": "辨壤术把微量魔力送入掌心接触的土中，依靠土粒间缝隙传导的细微震动，分辨颗粒粗细、湿度和夹杂的碎石腐叶。它只读取一把土自身携带的质地信息，不会沿地面追踪来源，也不能凭土样推断田块归谁所有或地契写在谁名下。施术者手中的土必须来自现场，离开土地的散土也能被读取，但读取结果只描述这一把土，不延伸至周围更大的地块。",
      "casting": "单膝跪地，用掌心压实一小把土，另一手食指在土面画一道短横，随后闭眼静候约二十次呼吸，让魔力沿缝隙走完一圈。",
      "failure": "魔力在干硬土块表面打滑，掌心只感到一阵发麻，土样随即碎散，无法给出可读的质地结果。若土中混有大量积水，震动会被水层吞没，施术者只得到模糊的潮湿感，分不清颗粒粗细与夹杂物。",
      "counters": [
        "在土样表面撒一层细沙，沙粒会打乱魔力沿缝隙的传导路径。",
        "把土样浸入水中，水层吸收震动，使读取结果模糊不清。"
      ],
      "socialConsequences": "西陲河谷的乡约常请人在分地或立契前辨明土质，好把贫瘠与肥沃写进约定，免得日后争执。中陆城市的园圃行会认可这种小术用于选苗床，却不承认它能替代地契与界石。琥珀海岸的码头工人会用它检查压舱土是否混入盐分，但若有人拿结果去指认货主，港务仍按货单与证人追究，不单凭一把土定责。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "刚入门时只能分出沙土与黏土，常把湿土误判为掺水。",
        "熟练后能辨出腐叶与碎石的大致比例，结果趋于稳定。",
        "老练者可在三十次呼吸内完成，仍只读取掌心那把土。",
        "精深者能察觉极细的盐粒混入，范围与耗时不变。"
      ]
    },
    {
      "id": "spell_earth_02",
      "theory": "松土术将魔力压入耕作层，使土粒之间的空隙短暂扩张，让板结的泥土变得松散透气。它只作用于一小片耕地表层，深度不超过一臂，不能翻出深埋的石块，也不能代替排石、施肥与播种。松开的土壤在魔力退去后会缓慢回沉，因此必须在有限时间内完成后续农活；若土中饱含积水，空隙会被水填满，松土效果大打折扣。",
      "casting": "双手十指张开插入土中，以两拇指为轴向外画弧，同时低声数到十，感到土面微微隆起即可收手。",
      "failure": "魔力分布不均时，土面会鼓起几处硬包，像被踩过的湿泥，反而更难下锄。若施术者用力过猛，魔力会沿裂缝窜出，把表层土掀成碎块，露出下面的生土，需要重新覆土才能播种。",
      "counters": [
        "在松过的土面泼水压实，水填满空隙后土壤重新板结。",
        "撒入粗砾并踩踏，砾石卡住土粒，使空隙无法维持。"
      ],
      "socialConsequences": "河谷农户在春播前会请人松一畦菜地，乡约只把这事当作邻里帮工，不另立规矩。中陆城市的园圃行会允许在自家围栏内施术，若在公共绿地操作则须先向管园人取得许可。琥珀海岸的码头货栈偶尔用它翻松压舱土，但港务规定若松土导致货堆倾覆或船板受损，仍按航运事故追究责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时松土深浅不一，常留下硬块需要二次返工。",
        "熟练后土面平整均匀，一畦地能在半刻内处理完。",
        "老练者能避开作物根系，仍不增加松土深度与面积。",
        "精深者可在湿土上稳定施术，效果依旧限于表层。"
      ]
    },
    {
      "id": "spell_earth_03",
      "theory": "压印术把魔力聚在脚掌或模具接触的软土上，使土粒沿接触面紧密排列，从而留下清晰的足印、蹄痕或印模。它只改变软土的排列，不能在硬石、木板或干土上留下痕迹，也不会把印记变成可追踪的魔法标记。印痕会随土中水分蒸发而逐渐模糊，因此需要趁土未干时查看或拓印。",
      "casting": "单脚站稳，另一脚掌或模具垂直压入软土，同时以指尖在土面外侧轻点三下，待脚印边缘不再塌落即可抬起。",
      "failure": "魔力过弱时脚印边缘会塌落，只留下一个模糊的浅坑，看不出纹路。若土太干或混有大量砂砾，压印会崩碎成散粒，无法得到完整形状；施术者重心不稳时还会踩出重叠的乱痕。",
      "counters": [
        "在软土表面铺一层干草或碎叶，脚掌无法直接接触土面。",
        "用平木板轻拍地面，震松土粒使已留下的印痕塌陷。"
      ],
      "socialConsequences": "西陲河谷的猎户与牧人会请人压出清晰蹄印，用于比对走失牲畜，乡约只把它当作寻常取证手段。中陆城市的巡夜队允许在泥地上压印记录可疑足迹，但不得以此代替人证与物证。琥珀海岸的港务在货损事故中会查看码头泥地上的压痕，若有人伪造印痕诬指他人，则按诬告追究责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时印痕深浅不一，纹路常被塌土糊住难以辨认。",
        "熟练后能压出完整足印，边缘整齐可供比对。",
        "老练者可在松湿土上一次成功，不必反复补压。",
        "精深者能控制印痕深浅，仍不能把印记留在硬地上。"
      ]
    }
  ]
}
